import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    b = []
    for _ in range(n):
        b.append(int(next(iterator)))

    a = [0] * n

    for i in range(n):
        nxt = (i + 1) % n
        curr_b = b[i]

        if a[nxt] == 0:
            if curr_b == 0:
                a[i] = 1
            else:
                a[i] = curr_b + 1
        else:
            if curr_b >= a[nxt]:
                print("NO")
                return
            if a[i] != 0:
                if a[i] % a[nxt] != curr_b:
                    print("NO")
                    return
            else:
                if curr_b == 0:
                    a[i] = a[nxt]
                else:
                    a[i] = curr_b

    for i in range(n):
        nxt = (i +1) % n
        if a[i] % a[nxt] != b[i]:
            print("NO")
            return

    print("YES")
    print(*(a))

if __name__ == "__main__":
    solve()
